import { createHash } from 'node:crypto';
import type { AppSnapshot } from '@lumacast/protocol';

/**
 * Bumped whenever the generation logic in `generator.ts` changes in any way
 * that could change the bytes a fixture class produces (new entities, a
 * different insertion order, a different default payload, ...). A manifest
 * generated by one version is not expected to match one generated by
 * another — that mismatch is the point: it makes generator drift visible
 * instead of silently comparing incompatible baselines.
 */
export const FIXTURE_GENERATOR_VERSION = 1;

export const FIXTURE_CLASSES = [
  'small',
  'large',
  'media-heavy',
  'theme-heavy',
  'talk-automation-heavy',
] as const;

export type FixtureClass = (typeof FIXTURE_CLASSES)[number];

export function isFixtureClass(value: string): value is FixtureClass {
  return (FIXTURE_CLASSES as readonly string[]).includes(value);
}

/**
 * Row counts per AppSnapshot table plus a couple of derived figures.
 *
 * `slideElements` is the raw `AppSnapshot.slideElements` length.
 * `deckSlideElements` is the subset attached to a deck-owned slide (i.e. one
 * present in `AppSnapshot.slides`). As of #211, `getSlideElements()` is
 * itself scoped to deck-owned slides (`WHERE presentation_id IS NOT NULL OR
 * lyric_id IS NOT NULL OR talk_id IS NOT NULL`), matching `getSlides()`
 * exactly — theme/overlay/stage container elements are excluded from
 * `AppSnapshot.slideElements` entirely and only reachable through their
 * owning container's own `elements` field. Before #211 this table was
 * unfiltered and the two counts could diverge; they're kept as separate
 * fields anyway so a regression there (the scoping drifting apart again)
 * shows up immediately as `slideElements > deckSlideElements` instead of
 * silently going unnoticed.
 */
export interface FixtureEntityCounts {
  libraries: number;
  playlists: number;
  playlistGroups: number;
  playlistEntries: number;
  presentations: number;
  lyrics: number;
  talks: number;
  slides: number;
  talkScriptBlocks: number;
  slideElements: number;
  deckSlideElements: number;
  mediaAssets: number;
  overlays: number;
  themes: number;
  stages: number;
  collections: number;
  cues: number;
  macros: number;
  triggerBindings: number;
}

export interface FixtureManifest {
  generatorVersion: number;
  /** Database `user_version` (schema version) the fixture was generated against. */
  schemaVersion: number;
  seed: string;
  fixtureClass: FixtureClass;
  entityCounts: FixtureEntityCounts;
  /** SHA-256 of the canonicalized snapshot content, hex-encoded. */
  contentHash: string;
}

function countDeckSlideElements(snapshot: AppSnapshot): number {
  const deckSlideIds = new Set(snapshot.slides.map((slide) => slide.id));
  return snapshot.slideElements.filter((element) => deckSlideIds.has(element.slideId)).length;
}

function countPlaylistsAndGroupsAndEntries(snapshot: AppSnapshot): {
  playlists: number;
  playlistGroups: number;
  playlistEntries: number;
} {
  let playlists = 0;
  let playlistGroups = 0;
  let playlistEntries = 0;
  for (const bundle of snapshot.libraryBundles) {
    playlists += bundle.playlists.length;
    for (const tree of bundle.playlists) {
      playlistGroups += tree.groups.length;
      for (const group of tree.groups) {
        playlistEntries += group.entries.length;
      }
    }
  }
  return { playlists, playlistGroups, playlistEntries };
}

export function computeEntityCounts(snapshot: AppSnapshot): FixtureEntityCounts {
  const { playlists, playlistGroups, playlistEntries } = countPlaylistsAndGroupsAndEntries(snapshot);
  return {
    libraries: snapshot.libraries.length,
    playlists,
    playlistGroups,
    playlistEntries,
    presentations: snapshot.presentations.length,
    lyrics: snapshot.lyrics.length,
    talks: snapshot.talks.length,
    slides: snapshot.slides.length,
    talkScriptBlocks: snapshot.talkScriptBlocks.length,
    slideElements: snapshot.slideElements.length,
    deckSlideElements: countDeckSlideElements(snapshot),
    mediaAssets: snapshot.mediaAssets.length,
    overlays: snapshot.overlays.length,
    themes: snapshot.themes.length,
    stages: snapshot.stages.length,
    collections: snapshot.collections.length,
    cues: snapshot.cues.length,
    macros: snapshot.macros.length,
    triggerBindings: snapshot.triggerBindings.length,
  };
}

/**
 * Deterministic JSON stringification: object keys are sorted recursively so
 * two structurally-identical values always serialize to the same string
 * regardless of insertion order. Array order is preserved as-is — it is
 * meaningful (it's driven by the deterministic `ORDER BY` clauses in
 * `store.ts`) and must contribute to the hash, not be normalized away.
 */
export function canonicalStringify(value: unknown): string {
  return JSON.stringify(sortKeysDeep(value));
}

function sortKeysDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(sortKeysDeep);
  }
  if (value !== null && typeof value === 'object') {
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(value as Record<string, unknown>).sort()) {
      sorted[key] = sortKeysDeep((value as Record<string, unknown>)[key]);
    }
    return sorted;
  }
  return value;
}

export function hashSnapshot(snapshot: AppSnapshot): string {
  return createHash('sha256').update(canonicalStringify(snapshot)).digest('hex');
}

/**
 * A stored manifest is only trustworthy as a baseline if it was produced by
 * the schema and generator logic in use *right now*. This is the mechanism
 * behind "record the schema version so an older fixture is detectable
 * rather than silently misleading" (#200): compare a manifest's recorded
 * versions against the versions currently in force before trusting its
 * counts or hash for a comparison.
 */
export function isManifestCurrent(
  manifest: FixtureManifest,
  current: { schemaVersion: number; generatorVersion?: number },
): boolean {
  return (
    manifest.schemaVersion === current.schemaVersion
    && manifest.generatorVersion === (current.generatorVersion ?? FIXTURE_GENERATOR_VERSION)
  );
}

export function buildManifest(params: {
  seed: string;
  fixtureClass: FixtureClass;
  schemaVersion: number;
  snapshot: AppSnapshot;
}): FixtureManifest {
  return {
    generatorVersion: FIXTURE_GENERATOR_VERSION,
    schemaVersion: params.schemaVersion,
    seed: params.seed,
    fixtureClass: params.fixtureClass,
    entityCounts: computeEntityCounts(params.snapshot),
    contentHash: hashSnapshot(params.snapshot),
  };
}
